-- Modify "signature" table
ALTER TABLE "public"."signature" ADD CONSTRAINT "signature_none_has_no_result" CHECK ((kind <> 'none'::public.signature_kind) OR (result IS NULL)), ADD CONSTRAINT "signature_verified_names_a_signer" CHECK ((result IS DISTINCT FROM 'verified'::public.signature_result) OR ((signer_issuer IS NOT NULL) AND (signer_identity IS NOT NULL) AND (bundle IS NOT NULL) AND (artifact_digest IS NOT NULL))), ADD COLUMN "bundle" jsonb NULL, ADD COLUMN "artifact_digest" bytea NULL, ADD COLUMN "signer_issuer" text NULL, ADD COLUMN "signer_identity" text NULL, ADD COLUMN "signed_at" timestamptz NULL, ADD COLUMN "log_index" bigint NULL, ADD COLUMN "reason" text NULL;
